from sc_lib import *
# ---- 11 Service Trust Portal and privacy
C(11,"What is the Service Trust Portal?","Microsoft's public site (**servicetrust.microsoft.com**) for **audit reports, certifications, compliance guides and security assessments** that show how Microsoft cloud services protect your data.")
C(11,"What kinds of documents are on the Service Trust Portal?","Independent **audit reports** (SOC, ISO, FedRAMP), **penetration test and security assessment** results, compliance guides and white papers.")
C(11,"Service Trust Portal: what is My Library?","A place to **save (pin) documents** you use often. You can be **notified when Microsoft updates them**.")
C(11,"Microsoft's six privacy principles?","**Control, Transparency, Security, Strong legal protections, No content-based targeting, Benefits to you.**")
C(11,"Privacy principle 'Control' vs 'Transparency'?","**Control:** you are in charge of your data, with easy tools and clear choices. **Transparency:** Microsoft is open about data collection and use so you can make informed decisions.")
C(11,"Privacy principle 'No content-based targeting'?","Microsoft does **not use your email, chat, files or other personal content to target advertising** to you.")
C(11,"Privacy principles 'Strong legal protections' and 'Benefits to you'?","**Strong legal protections:** Microsoft respects local privacy laws and fights for privacy as a human right. **Benefits to you:** when data is collected, it is used to benefit you and improve your experience.")
Q(11,"An auditor asks for Microsoft's SOC 2 audit report for Azure. Where can you download it?","Service Trust Portal",["Microsoft Defender portal","Microsoft Entra admin center","Azure Advisor"],"The Service Trust Portal publishes independent audit reports and compliance documents.")
Q(11,"Which Microsoft privacy principle says your email and chat content is not used to target ads?","No content-based targeting",["Transparency","Strong legal protections","Benefits to you"],"No content-based targeting: personal content is not used for advertising.")
Q(11,"Which privacy principle is about Microsoft being open about what data it collects and how it is used?","Transparency",["Control","Security","Benefits to you"],"Transparency is being open about collection and use. Control is about your choices over the data.")
Q(11,"On the Service Trust Portal, which feature lets you save documents and get notified when they are updated?","My Library",["Compliance Manager","Content explorer","Secure score"],"My Library pins documents and can notify you of updates.")
Q(11,"Which of these is NOT one of Microsoft's six privacy principles?","Zero standing access",["Control","Security","Strong legal protections"],"The six are control, transparency, security, strong legal protections, no content-based targeting and benefits to you.")
Q(11,"Which TWO can you find on the Service Trust Portal?",["Independent audit reports for Microsoft cloud services","Penetration test and security assessment reports"],["Your tenant's sign-in logs","Your organization's secure score"],"The portal publishes Microsoft's own compliance evidence. Tenant data lives in your admin portals.")
YN(11,["The Service Trust Portal shows how Microsoft cloud services meet compliance standards.","Under Microsoft's privacy principles, customer content is used to target advertising.","'Control' means customers have tools and choices to manage their own data."],[1,0,1],"The portal provides compliance evidence. Content is never used for ad targeting. Control puts the customer in charge.")
D(11,"Service Trust Portal","Microsoft Purview portal","Download Microsoft's ISO and SOC audit reports.",0,"The Service Trust Portal holds Microsoft's audit reports. The Purview portal is where you manage your own compliance.")
D(11,"Control","Transparency","Microsoft is open about what it collects and why.",1,"Transparency is openness. Control is your ability to manage the data.")
D(11,"Security","No content-based targeting","Your files and email are not used for ads.",1,"That is no content-based targeting. Security is protecting data with strong safeguards and encryption.")
# ---- 12 Compliance management
C(12,"What is the Microsoft Purview portal?","**purview.microsoft.com**. One place for Purview's **data security, data governance, and risk and compliance** solutions.")
C(12,"What is Compliance Manager?","A Purview solution that helps you **assess and manage compliance** across your multicloud environment: prebuilt **assessments** for regulations, step-by-step **improvement actions**, and a **compliance score**.")
C(12,"Compliance Manager: controls, assessments, regulations (templates), improvement actions?","A **regulation** template (GDPR, ISO 27001) creates an **assessment**. The assessment is made of **controls**. Each control is met by **improvement actions** with guidance you carry out.")
C(12,"Compliance Manager: three control types?","**Microsoft-managed** (Microsoft implements), **your controls** (customer-managed, you implement), **shared** (both).")
C(12,"What is the compliance score?","A **risk-based** percentage showing progress on **improvement actions**. It helps you prioritize. It is **not a guarantee** of being compliant with a regulation.")
C(12,"Compliance score vs secure score?","**Compliance score:** Purview Compliance Manager, progress toward regulations and standards. **Secure score:** Microsoft Defender, strength of your security configuration.")
C(12,"What does the default Compliance Manager assessment cover?","The **data protection baseline**: key controls drawn from common regulations and standards, so every organization starts with an initial score.")
Q(12,"You must track your organization's progress toward GDPR requirements with recommended actions. Which tool should you use?","Compliance Manager",["Microsoft Sentinel","Azure Policy","Service Trust Portal"],"Compliance Manager has prebuilt assessments for regulations, improvement actions and a compliance score.")
Q(12,"What does the compliance score measure?","Progress in completing improvement actions that reduce compliance risk",["The number of blocked sign-ins","How many resources pass Azure Policy","The percentage of emails encrypted"],"The compliance score reflects completed improvement actions, weighted by risk.")
Q(12,"In Compliance Manager, a control that Microsoft implements on your behalf is called what?","Microsoft-managed control",["Your control","Shared control","Technical control"],"Microsoft-managed controls are Microsoft's responsibility. Your controls are yours. Shared controls are both.")
Q(12,"Where do you open Compliance Manager?","Microsoft Purview portal",["Microsoft Defender portal","Microsoft Entra admin center","Azure portal Cost Management"],"Compliance Manager is a Microsoft Purview solution.")
Q(12,"Your compliance score is 85%. What does that tell you?","You have completed most recommended improvement actions, but it does not prove legal compliance",["You are certified as compliant with all regulations","85% of your users have MFA","Microsoft has audited your tenant"],"The score measures progress on actions. It is not a certification or a guarantee.")
Q(12,"Which TWO does Compliance Manager provide?",["Prebuilt assessments for common regulations","Step-by-step guidance on improvement actions"],["Real-time blocking of phishing emails","Just-in-time VM access"],"Compliance Manager provides assessments, improvement actions and the compliance score.")
YN(12,["Compliance Manager includes templates for regulations and standards.","A high compliance score guarantees that the organization is compliant with a regulation.","Shared controls are implemented by both Microsoft and the customer."],[1,0,1],"Templates create assessments. The score is not a guarantee. Shared controls belong to both.")
D(12,"Compliance score","Secure score","Progress toward meeting regulations such as GDPR.",0,"Compliance score is about regulations. Secure score is about security posture.")
D(12,"Microsoft-managed control","Your control","You implement it yourself.",1,"Your controls are customer-managed. Microsoft-managed are done by Microsoft.")
D(12,"Compliance Manager","Service Trust Portal","Tracks your own improvement actions.",0,"Compliance Manager manages your compliance. The Service Trust Portal shows Microsoft's evidence.")
# ---- 13 Information protection and data lifecycle
C(13,"Microsoft Purview Information Protection: the four steps?","**Know your data, protect your data, prevent data loss, govern your data.**")
C(13,"Sensitive information types vs trainable classifiers?","**Sensitive information types:** pattern-based (credit card, passport numbers). **Trainable classifiers:** AI that learns from examples to recognize kinds of content (resumes, source code, contracts).")
C(13,"Content explorer vs Activity explorer?","**Content explorer:** a current snapshot of **which items** have a sensitivity label, retention label or sensitive info type, and where they are. **Activity explorer:** the **history of what was done** to labeled content (label changed, file copied to USB, printed).")
C(13,"What is a sensitivity label? What can it do?","A tag you apply to documents and emails. It is **customizable, stored as clear-text metadata, and persistent** (it travels with the content). It can **encrypt**, add **markings** (header, footer, watermark), and protect containers like Teams and sites. **One sensitivity label per item.**")
C(13,"What is a sensitivity label policy?","How labels are **published** to users and groups. Can set a **default label**, require **justification to lower** a label, and make **labeling mandatory**.")
C(13,"What is data loss prevention (DLP)?","Policies that **detect and stop inappropriate sharing of sensitive information** across Exchange, SharePoint, OneDrive, Teams and devices (Endpoint DLP). Actions: block, show a **policy tip**, alert.")
C(13,"Retention policy vs retention label?","**Retention policy:** the same settings for a whole location (site, mailbox). **Retention label:** set per item (document, email, folder). An item can have **only one retention label** at a time.")
C(13,"What is records management?","Declaring items as **records**: they get restrictions (cannot be deleted, edits limited), activities are logged, and at the end there is **disposition review** and proof of disposition.")
C(13,"What can retention settings do?","**Retain only**, **delete only**, or **retain then delete**. Labels can be published for users to apply or applied automatically.")
Q(13,"A document must stay encrypted and show a 'Confidential' watermark even after it is emailed outside the company. What should you apply?","A sensitivity label",["A retention label","An NSG rule","An access review"],"Sensitivity labels are persistent and can encrypt and mark content. Retention labels control how long content is kept.")
Q(13,"You need to see that a user copied a labeled file to a USB drive yesterday. Which tool shows this?","Activity explorer",["Content explorer","Compliance Manager","Service Trust Portal"],"Activity explorer shows the history of actions on labeled content. Content explorer shows what exists and where.")
Q(13,"Users must be warned and blocked when they try to email credit card numbers outside the company. What should you configure?","A data loss prevention policy",["A retention policy","A Conditional Access policy","A sensitivity label policy"],"DLP detects sensitive information in use and blocks or warns about inappropriate sharing.")
Q(13,"All email in every mailbox must be kept for seven years and then deleted. What is the simplest configuration?","A retention policy applied to Exchange mailboxes",["A sensitivity label","A DLP policy","An eDiscovery hold"],"A retention policy applies the same retention settings across a whole location.")
Q(13,"Which classification method recognizes content such as resumes by learning from example documents?","Trainable classifiers",["Sensitive information types","Exact keyword match","Retention labels"],"Trainable classifiers use AI trained on examples. Sensitive information types match patterns.")
Q(13,"Which TWO statements about sensitivity labels are true?",["The label stays with the content when it moves","An item can have only one sensitivity label at a time"],["Labels are removed when a file is emailed","Labels can only be applied by administrators"],"Labels are persistent and one per item. Users apply them, or they are applied automatically.")
YN(13,["A document can have multiple retention labels applied at the same time.","Content explorer shows where sensitive items are located.","DLP policies can show a policy tip to warn users before they share sensitive data."],[0,1,1],"One retention label per item. Content explorer shows location and labels. Policy tips educate users at the moment of sharing.")
M(13,"Match each need to the Microsoft Purview capability.",[("Encrypt and watermark a file","Sensitivity label"),("Stop credit card numbers leaving in email","Data loss prevention"),("Keep contracts for 10 years","Retention label"),("Lock an item so it cannot be deleted","Records management")],"Labels protect, DLP prevents leaks, retention governs lifetime, records management locks important items.")
D(13,"Sensitivity label","Retention label","Controls how long content is kept before deletion.",1,"Retention labels govern lifetime. Sensitivity labels classify and protect.")
D(13,"Content explorer","Activity explorer","History of what users did with labeled files.",1,"Activity explorer is the history. Content explorer is the current inventory.")
D(13,"Retention policy","Retention label","Applies at item level, such as one document.",1,"Labels are per item. Policies cover a whole location.")
D(13,"Sensitive information types","Trainable classifiers","Pattern matching, such as a credit card number format.",0,"Sensitive information types use patterns. Trainable classifiers learn from examples.")
# ---- 14 Insider risk, eDiscovery, audit
C(14,"What is Insider Risk Management?","A Purview solution to **detect, investigate and act on risky activity by people inside** the organization: data theft by departing employees, data leaks, security policy violations.")
C(14,"Insider Risk Management workflow?","**Policies** define risk indicators, **alerts** are raised, then **triage**, **investigate** in a case, and take **action** (reminder notice, or escalate).")
C(14,"How does Insider Risk Management protect privacy?","**Privacy by design:** usernames are **pseudonymized by default**, access is role-based, and investigator actions are audited.")
C(14,"What is eDiscovery?","Identifying and delivering **electronic information as evidence in legal cases**. Purview eDiscovery searches mailboxes, Teams, SharePoint and OneDrive.")
C(14,"eDiscovery: cases, holds, search, export?","A **case** groups everything for one investigation. A **hold** preserves content so it cannot be deleted. **Search** finds content. **Export** delivers it. Premium features add review sets and analytics.")
C(14,"Microsoft Purview Audit (Standard)?","**On by default.** Records user and admin activity across Microsoft 365 in the unified audit log. Records are kept **180 days**.")
C(14,"Microsoft Purview Audit (Premium)?","Adds **longer retention** (one year by default for Entra ID, Exchange, SharePoint and OneDrive, **up to 10 years** with an add-on), **audit log retention policies**, and **intelligent insights** for investigations.")
C(14,"Hold vs retention policy?","An **eDiscovery hold** preserves content tied to a legal **case**. A **retention policy** governs content lifetime for compliance generally.")
Q(14,"An employee who has resigned is downloading large numbers of confidential files. Which solution is designed to detect this?","Insider Risk Management",["eDiscovery","Compliance Manager","Azure DDoS Protection"],"Insider Risk Management detects risky activity by insiders such as data theft by departing employees.")
Q(14,"Legal needs all email and Teams messages about a lawsuit preserved and exported. Which solution should you use?","eDiscovery",["Audit (Standard)","Insider Risk Management","Data loss prevention"],"eDiscovery cases let you hold, search and export content as legal evidence.")
Q(14,"You need to find out which admin changed a mailbox permission last week. Where do you look?","Microsoft Purview Audit",["Content explorer","Compliance score","Service Trust Portal"],"The unified audit log records user and admin activities.")
Q(14,"How long does Audit (Standard) keep audit records by default?","180 days",["30 days","1 year","10 years"],"Audit (Standard) retains records for 180 days. Longer retention needs Audit (Premium).")
Q(14,"In eDiscovery, what does placing a hold do?","Preserves content so it cannot be permanently deleted during the case",["Encrypts the content with a sensitivity label","Blocks the user from signing in","Deletes the content after export"],"A hold preserves content relevant to a case.")
Q(14,"Which TWO are Audit (Premium) capabilities?",["Audit log retention policies","Retention of audit records for up to 10 years with an add-on"],["Blocking phishing links","Creating access packages"],"Audit (Premium) adds retention policies, longer retention and intelligent insights.")
YN(14,["Insider Risk Management pseudonymizes usernames by default.","Audit (Standard) must be manually purchased and turned on before any activity is recorded.","eDiscovery can search content in Exchange mailboxes and Microsoft Teams."],[1,0,1],"Pseudonymization protects privacy. Audit (Standard) is on by default. eDiscovery searches Microsoft 365 locations.")
D(14,"Audit (Standard)","Audit (Premium)","Keeps records up to 10 years with an add-on license.",1,"Premium extends retention. Standard is 180 days.")
D(14,"eDiscovery","Insider Risk Management","Find and export evidence for a legal case.",0,"eDiscovery is for legal evidence. Insider Risk Management detects risky user activity.")
D(14,"eDiscovery hold","Retention policy","Preserves content tied to a specific legal case.",0,"Holds are case-based. Retention policies apply broadly for compliance.")
